contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll accept two inputs: amount to send and an arbitrary timestamp-influencing nonce (unused but ensures variability).
    function run(uint amount, uint /*unused*/) public payable {
        // We will only send Ether via the parameter `amount`.
        require(address(this).balance >= amount, "insufficient balance to send");

        // Read pre-call observable values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Make the call to fallback and capture whether it reverted.
        bool reverted;
        // We must call the fallback by sending to the contract address with no data.
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule: If call succeeded and amount == 10 ether then pastBlockTime must have been advanced
        // to the current block.timestamp (non-decreasing and strictly greater than previous) and the balance
        // behavior depends on block.number%15: if divisible then contract drained to 0, else increased by 10 ether.
        // If the call reverted, nothing can be assumed about state change (except it did revert).
        assert(
            // If reverted, we make no strong claim (allow any outcome)
            reverted
            || (
                // call succeeded
                amount == 10 ether
                // pastBlockTime strictly increased (require block.timestamp > previous)
                && afterPast > beforePast
                // If block.number%15==0 then contract should have paid out entire balance (be zero)
                && ((block.number % 15 == 0) ? (afterBal == 0) : (afterBal == beforeBal + 10 ether))
            )
        );
    }

    // Allow receiving Ether so that this test contract can fund calls
    receive() external payable {}
}

