contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes amount and an extraFlag (unused except as fuzz input) to be fully general.
    // It will call the fallback of c by sending `amount` wei.
    function run(uint amount, uint extraFlag) public payable {
        // ensure this contract has enough balance to send amount
        require(address(this).balance >= amount);

        // observe before values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the payable call and capture whether it reverted
        bool reverted;
        // call fallback by sending to c with empty calldata
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint myBal = address(this).balance;

        // General rule asserted:
        // - If amount != 10 ether, the fallback requires msg.value == 10 ether and thus must revert,
        //   so state (pastBlockTime) remains unchanged and contract balance unchanged.
        // - If amount == 10 ether, then either it reverted due to timestamp not greater than pastBlockTime,
        //   in which case pastBlockTime and balances remain unchanged; otherwise it updates pastBlockTime to block.timestamp,
        //   and if block.number % 15 == 0 then the contract's balance becomes 0 and the caller (this contract) receives that balance,
        //   else the contract balance increases by amount and pastBlockTime equals block.timestamp.
        assert(
            // Case A: amount != 10 ether -> must revert and no state change
            ((amount != 10 ether) && reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // Case B: amount == 10 ether and reverted -> no state change
            ((amount == 10 ether) && reverted && afterPast == beforePast && afterBal == beforeBal)
            ||
            // Case C: amount == 10 ether and succeeded -> pastBlockTime updated and balances updated accordingly
            ((amount == 10 ether) && !reverted && afterPast == block.timestamp && (
                // if block.number % 15 == 0 then contract balance is 0 and this contract's balance increased by beforeBal
                ((block.number % 15 == 0) && afterBal == 0)
                ||
                // else contract balance increased by amount
                ((block.number % 15 != 0) && afterBal == beforeBal + amount)
            ))
        );
    }

    // allow receiving Ether when C transfers out to this contract
    receive() external payable {}
}

